const DURATION = /^([0-9]+)(ms|s|m|h)$/
const DURATION_MS = { ms: 1n, s: 1000n, m: 60000n, h: 3600000n }
const INTEGER = /^-?(0|[1-9][0-9]*)$/

/**
 * Coerce one setting's raw text to its declared type, and render it back.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting.
 * @param {string} text - the raw text a layer wrote, or the schema default.
 * @returns {string} the text as the type renders it.
 * @throws {Error} when `text` does not fit the declared type; `message` is the specification's
 *   wording, without the position it was written at.
 */
export function coerce(declared, text) {
  switch (declared.type) {
    case 'string':
      return text
    case 'integer':
      if (!INTEGER.test(text)) throw new Error(`${declared.key} is not an integer: ${text}`)
      return text
    case 'boolean':
      if (text !== 'true' && text !== 'false') throw new Error(`${declared.key} is not a boolean: ${text}`)
      return text
    case 'enum':
      if (!declared.members.includes(text)) {
        throw new Error(`${declared.key} is not one of ${declared.members.join('|')}: ${text}`)
      }
      return text
    case 'duration': {
      const match = DURATION.exec(text)
      if (!match) throw new Error(`${declared.key} is not a duration: ${text}`)
      return String(BigInt(match[1]) * DURATION_MS[match[2]])
    }
    case 'list': {
      if (text === '') return ''
      const items = text.split(',').map(item => item.trim())
      if (items.some(item => item === '')) throw new Error(`${declared.key} has an empty item: ${text}`)
      const seen = new Set()
      const deduped = []
      for (const item of items) {
        if (!seen.has(item)) {
          seen.add(item)
          deduped.push(item)
        }
      }
      return deduped.join(',')
    }
    default:
      throw new Error(`unknown type ${declared.type}`)
  }
}"}

